$('pause').onclick=()=>setPaused(!paused);$('light').onclick=()=>setNight(!night);$('feed').onclick=feed;$('speed').onchange=e=>speed=Number(e.target.value);$('home-view').onclick=()=>{controls.autoRotate=false;$('orbit').setAttribute('aria-pressed','false');home();};$('orbit').onclick=()=>{controls.autoRotate=!controls.autoRotate;$('orbit').setAttribute('aria-pressed',String(controls.autoRotate));};$('reset').onclick=()=>{elapsed=0;feedingUntil=0;food.visible=false;speed=1;$('speed').value='1';setNight(false);fish.forEach(f=>{f.group.position.copy(f.initial);f.velocity.set(2,0,0);f.target.copy(f.initial);f.group.rotation.set(0,0,0);f.tail.rotation.y=0;f.top.rotation.x=0;f.bottom.rotation.x=0;f.next=0;f.state=[...INITIAL[f.index]];f.action=0;f.nextAction=0;f.nextIntake=0;f.consumed=0;});clock.reset();behaviorRandom=seededRandom(73);last=0;uiTime=0;$('event-log').textContent=T('Simulation reset. E and each fish\'s activity tendency B stay fixed for this run.','已重置模拟；E 与个体活动倾向 B 在本轮保持固定。');selectFish(0);setPaused(matchMedia('(prefers-reduced-motion: reduce)').matches);controls.autoRotate=false;$('orbit').setAttribute('aria-pressed','false');home();updateUI();};cards.onclick=e=>{const c=e.target.closest('[data-id]');if(c)selectFish(Number(c.dataset.id));};
const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();let pointerStart;canvas.addEventListener('pointerdown',e=>pointerStart=[e.clientX,e.clientY]);canvas.addEventListener('pointerup',e=>{if(!pointerStart||Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>5)return;const r=canvas.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hits=ray.intersectObjects(fish.map(f=>f.group),true);if(hits.length){let obj=hits[0].object;while(obj.parent&&obj.parent!==scene)obj=obj.parent;const i=fish.findIndex(f=>f.group===obj);if(i>=0)selectFish(i);}});
canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key))return;e.preventDefault();const offset=camera.position.clone().sub(controls.target);const s=new THREE.Spherical().setFromVector3(offset);if(e.key==='ArrowLeft')s.theta-=.12;if(e.key==='ArrowRight')s.theta+=.12;if(e.key==='ArrowUp')s.phi-=.08;if(e.key==='ArrowDown')s.phi+=.08;if(e.key==='+')s.radius*=.92;if(e.key==='-')s.radius*=1.08;s.phi=THREE.MathUtils.clamp(s.phi,.15,Math.PI*.49);s.radius=THREE.MathUtils.clamp(s.radius,80,270);camera.position.copy(controls.target).add(new THREE.Vector3().setFromSpherical(s));controls.update();});
function step(dt){elapsed+=dt;const feeding=feedingUntil>elapsed;for(const f of fish){const p=f.group.position,i=f.index;if(elapsed>=f.nextAction){const previous=f.action;f.action=chooseAction(f.state,f.boldness,behaviorRandom);f.nextAction=elapsed+.75;if(previous!==f.action)f.next=0;}
if(elapsed>=f.next||p.distanceTo(f.target)<3){f.next=elapsed+3+behaviorRandom()*5;if(f.action===1)f.target.set(feedingX(i),39,17);else if(f.action===3)f.target.set(i%2?-30:30,14,-7);else if(f.action===2)f.target.copy(p);else f.target.set(-36+behaviorRandom()*72,14+behaviorRandom()*24,4+behaviorRandom()*19);}
const pace=[2.6,3.6,0,2.8,9][f.action]*paces[i]*(1-.6*f.state[3])*(night?.65:1);const desired=f.target.clone().sub(p).normalize().multiplyScalar(pace);for(const other of fish){if(other===f)continue;const d=p.clone().sub(other.group.position),len=d.length();if(len<9&&len>.01)desired.add(d.multiplyScalar((9-len)/len*.6));}for(const o of obstacles){const d=p.clone().sub(o.p),len=d.length();if(len<o.r+3&&len>.01)desired.add(d.multiplyScalar((o.r+3-len)/len*2));}f.velocity.lerp(desired,Math.min(dt*1.6,1));f.velocity.clampLength(0,10);const previousPosition=p.clone();p.addScaledVector(f.velocity,dt);p.x=THREE.MathUtils.clamp(p.x,-38,38);p.y=THREE.MathUtils.clamp(p.y,11,39);p.z=THREE.MathUtils.clamp(p.z,-22,24);f.velocity.copy(p).sub(previousPosition).divideScalar(dt);
let intake=0;if(feeding&&p.distanceTo(V(feedingX(i),39,17))<6&&elapsed>=f.nextIntake&&behaviorRandom()<intakeChance(f.state)){intake=1;f.consumed++;f.nextIntake=elapsed+.8;$('event-log').textContent=T(`${shownNames[i]} ate in the feeding area (simulated meal ${f.consumed}); H drops by 0.12.`,`${names[i]}在投喂区发生第 ${f.consumed} 次模拟进食，H 降低 0.12。`);}f.state=updateState(f.state,dt,intake,0,f.action===2);
const angle=Math.atan2(-f.velocity.z,f.velocity.x);let delta=THREE.MathUtils.euclideanModulo(angle-f.group.rotation.y+Math.PI,Math.PI*2)-Math.PI;f.group.rotation.y+=delta*Math.min(dt*2,1);f.group.rotation.z=THREE.MathUtils.clamp(f.velocity.y*.035,-.17,.17);f.tail.rotation.y=Math.sin(elapsed*6+i)*.27;f.top.rotation.x=Math.sin(elapsed*3+i)*.025;f.bottom.rotation.x=-Math.sin(elapsed*3+i)*.025;}
for(let i=0;i<65;i++){bubblePositions[i*3+1]+=dt*(1+i%3);if(bubblePositions[i*3+1]>47)bubblePositions[i*3+1]=14;}bubbleGeo.attributes.position.needsUpdate=true;if(food.visible){foodGeo.attributes.position.needsUpdate=true;if(!feeding)food.visible=false;}}
function labels(){fish.forEach((f,i)=>{const point=f.group.position.clone().add(V(0,-9,0)).project(camera);const el=labelElements[i];el.style.left=`${(point.x*.5+.5)*100}%`;el.style.top=`${(-point.y*.5+.5)*100}%`;el.hidden=point.z>1||point.x<-1||point.x>1||point.y<-1||point.y>1;});}
const clock=fixedClock(step);
$('disturb').onclick=()=>{fish.forEach(f=>{f.state=updateState(f.state,0,0,1,false);f.nextAction=0;});$('event-log').textContent=T('Simulated disturbance: every fish\'s S rises by 0.18, then slowly recovers.','模拟惊扰：每条鱼的 S 增加 0.18，随后缓慢恢复。');updateUI();};
document.addEventListener('visibilitychange',()=>{last=0;});
function frame(now){const dt=last?Math.max(0,(now-last)/1000):0;last=now;if(!paused&&!document.hidden){clock.advance(dt,speed);uiTime+=dt;if(uiTime>.3){updateUI();uiTime=0;}}controls.update();labels();renderer.render(scene,camera);requestAnimationFrame(frame);}selectFish(0);setPaused(paused);updateUI();requestAnimationFrame(frame);
// The ten-day page supplies precomputed synthetic snapshots; this scene never infers real-fish state.
if(embeddedTimeline){
  setPaused(true);
  window.addEventListener('message',e=>{
    if(e.origin!==location.origin||e.source!==window.parent||e.data?.kind!=='fishmood:synthetic-frame')return;
    const points=e.data.points;
    if(!Array.isArray(points)||points.length!==3)return;
    for(let i=0;i<3;i++){
      const point=points[i],position=point?.position,state=point?.state;
      if(!Array.isArray(position)||position.length!==3||!position.every(Number.isFinite)||!state||!['H','S','E'].every(k=>Number.isFinite(state[k])))return;
    }
    points.forEach((point,i)=>{
      const f=fish[i],p=point.position;
      f.group.position.set(THREE.MathUtils.clamp(p[0],-38,38),THREE.MathUtils.clamp(p[1],11,39),THREE.MathUtils.clamp(p[2],-22,24));
      f.target.copy(f.group.position);f.velocity.set(0,0,0);
      f.state=[THREE.MathUtils.clamp(point.state.H,0,1),THREE.MathUtils.clamp(point.state.S,0,1),THREE.MathUtils.clamp(point.state.E,0,1),f.state[3]];
      f.action=Number.isInteger(point.action)&&point.action>=0&&point.action<ACTION_NAMES.length?point.action:0;
    });
    setNight((e.data.minute%1440)<420||(e.data.minute%1440)>=1140);
    selectFish(Number.isInteger(e.data.selected)?e.data.selected:0);
    document.body.dataset.syntheticMinute=String(e.data.minute);
    document.body.dataset.selectedFish=String(selected);
    updateUI();
  });
  window.parent.postMessage({kind:'fishmood:scene-ready'},location.origin);
}
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();setPaused(true);$('running-label').textContent=T('Graphics connection lost. Please refresh the page.','图形连接中断，请刷新页面');});
if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'set_aquarium_simulation',description:'设置三维鱼缸模拟、选择鱼和恢复正面视角；数据仅为模拟。',inputSchema:{type:'object',properties:{paused:{type:'boolean'},night:{type:'boolean'},selectedFish:{type:'integer',minimum:0,maximum:names.length-1},feed:{type:'boolean'},home:{type:'boolean'},orbit:{type:'boolean'}},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('需要参数对象');for(const [k,v] of Object.entries(input)){if(!['paused','night','selectedFish','feed','home','orbit'].includes(k))throw Error('未知参数');if(k==='selectedFish'){if(!Number.isInteger(v)||v<0||v>=fish.length)throw Error('鱼编号必须为 0–2');}else if(typeof v!=='boolean')throw Error('需要布尔值');}if(input.night!==undefined)setNight(input.night);if(input.selectedFish!==undefined)selectFish(input.selectedFish);if(input.feed)feed();if(input.paused!==undefined)setPaused(input.paused);if(input.home)home();if(input.orbit!==undefined){controls.autoRotate=input.orbit;$('orbit').setAttribute('aria-pressed',String(input.orbit));}updateUI();return{simulation:true,fishCount:fish.length,selectedFish:selected,night,paused,feeding:elapsed<feedingUntil,orbit:controls.autoRotate};}})).catch(()=>{});}
